import { useMemo, useState, type FormEvent } from "react";
import { useLocation } from "wouter";
import { ArrowLeft, CalendarDays, Check, Download, LoaderCircle, Plus, Printer, Scissors, Wallet, Boxes, ChartNoAxesColumn, BadgeDollarSign, Repeat2, ShieldAlert } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { trpc } from "@/lib/trpc";

type Section = "caixa" | "financeiro" | "planos" | "promocoes" | "estoque" | "comissoes" | "relatorios";
const sectionByPath: Record<string, Section> = { "/app/caixa": "caixa", "/app/financeiro": "financeiro", "/app/planos": "planos", "/app/promocoes": "promocoes", "/app/estoque": "estoque", "/app/comissoes": "comissoes", "/app/relatorios": "relatorios" };
const sectionLabels: Record<Section, string> = { caixa: "Caixa", financeiro: "Financeiro", planos: "Planos", promocoes: "Promoções", estoque: "Estoque", comissoes: "Comissões", relatorios: "Relatórios" };
const sectionIcons: Record<Section, typeof Wallet> = { caixa: Wallet, financeiro: BadgeDollarSign, planos: Repeat2, promocoes: BadgeDollarSign, estoque: Boxes, comissoes: Scissors, relatorios: ChartNoAxesColumn };
const money = (value: number | string | null | undefined) => Number(value ?? 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const dateKey = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const asStart = (key: string) => new Date(`${key}T00:00:00`);
const asEnd = (key: string) => new Date(`${key}T23:59:59.999`);
const inputClass = "mt-1.5 h-10 w-full rounded-md border border-stone-200 bg-white px-3 text-sm outline-none focus:border-amber-700";
const buttonClass = "inline-flex min-h-10 items-center justify-center gap-2 rounded-md bg-stone-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-stone-700 disabled:cursor-not-allowed disabled:opacity-50";
const outlineClass = "inline-flex min-h-10 items-center justify-center gap-2 rounded-md border border-stone-200 bg-white px-3 py-2 text-sm text-stone-700 hover:bg-stone-50 disabled:opacity-50";
const methodName: Record<string, string> = { cash: "Dinheiro", pix: "Pix", credit: "Crédito", debit: "Débito", other: "Outro" };
const statusName: Record<string, string> = { active: "Ativo", expired: "Vencido", delinquent: "Inadimplente", paused: "Pausado", cancelled: "Cancelado", open: "Em aberto", paid: "Pago" };
const campaignKindLabel: Record<"service_discount" | "time_discount" | "combo", string> = { service_discount: "Serviços selecionados", time_discount: "Dia e horário", combo: "Combo de serviços" };

export default function BusinessConsole() {
  const [location, setLocation] = useLocation();
  const queryClient = useQueryClient();
  const [from, setFrom] = useState(() => dateKey(new Date(new Date().getFullYear(), new Date().getMonth(), 1)));
  const [to, setTo] = useState(() => dateKey(new Date()));
  const [kindFilter, setKindFilter] = useState<"all" | "income" | "expense">("all");
  const [paymentFilter, setPaymentFilter] = useState("");
  const [barberFilter, setBarberFilter] = useState("");
  const [serviceFilter, setServiceFilter] = useState("");
  const [cashFloat, setCashFloat] = useState("0");
  const [cashCount, setCashCount] = useState("");
  const [transactionForm, setTransactionForm] = useState({ kind: "expense" as "income" | "expense", category: "Aluguel", description: "", amount: "", paymentMethod: "pix" as "cash" | "pix" | "credit" | "debit" | "other", machineFee: "0", dueAt: "" });
  const [planForm, setPlanForm] = useState({ name: "", monthlyPrice: "", usageLimit: "", validityDays: "30", description: "", serviceIds: [] as number[] });
  const [couponForm, setCouponForm] = useState({ code: "", discountType: "percentage" as "percentage" | "fixed", discountValue: "10", validFrom: "", validUntil: "", usageLimit: "" });
  const [promotionForm, setPromotionForm] = useState({ name: "", kind: "service_discount" as "service_discount" | "time_discount" | "combo", discountType: "percentage" as "percentage" | "fixed", discountValue: "10", serviceIds: [] as number[], daysOfWeek: [] as number[], startTime: "09:00", endTime: "12:00", startsAt: "", endsAt: "" });
  const [subscriptionForm, setSubscriptionForm] = useState({ customerId: "", planId: "", paymentMethod: "pix" as "cash" | "pix" | "credit" | "debit" | "other", amount: "" });
  const [productForm, setProductForm] = useState({ name: "", sku: "", costPrice: "", salePrice: "", quantity: "0", minimumQuantity: "0", useInternally: false });
  const [movementForm, setMovementForm] = useState({ productId: "", kind: "in" as "in" | "out" | "internal_use" | "adjustment", quantity: "1", note: "" });
  const [commissionForm, setCommissionForm] = useState({ barberId: "", serviceId: "", scope: "all" as "service" | "product" | "plan" | "all", calculation: "percentage" as "percentage" | "fixed_per_service" | "chair_rent", value: "40", planPercentage: "20" });
  const [settlementForm, setSettlementForm] = useState({ barberId: "", discounts: "0", advances: "0" });
  const [settlementPayment, setSettlementPayment] = useState("pix");
  const [recurringForm, setRecurringForm] = useState({ name: "", category: "Conta fixa", amount: "", recurrence: "monthly" as "weekly" | "monthly" | "yearly", nextDueAt: dateKey(new Date()) });
  const [renewingId, setRenewingId] = useState<number | null>(null);
  const [renewAmount, setRenewAmount] = useState("");
  const [renewMethod, setRenewMethod] = useState("pix");

  const section = sectionByPath[location] ?? "caixa";
  const dateRange = useMemo(() => ({ from: asStart(from), to: asEnd(to) }), [from, to]);
  const me = trpc.management.tenant.me.useQuery(undefined, { retry: false });
  const role = me.data?.staff.role;
  const isOwner = role === "owner";
  const isBarber = role === "barber";
  const cash = trpc.business.finance.cashState.useQuery(undefined, { enabled: !!role && (section === "caixa" || section === "financeiro"), retry: false });
  const summary = trpc.business.finance.summary.useQuery(dateRange, { enabled: !!isOwner && section === "financeiro" });
  const transactions = trpc.business.finance.transactions.useQuery({ ...dateRange, kind: kindFilter === "all" ? undefined : kindFilter, paymentMethod: paymentFilter ? paymentFilter as "cash" | "pix" | "credit" | "debit" | "other" : undefined, barberId: barberFilter ? Number(barberFilter) : undefined, serviceId: serviceFilter ? Number(serviceFilter) : undefined }, { enabled: !!isOwner && (section === "financeiro" || section === "relatorios") });
  const payable = trpc.business.finance.accountsPayable.useQuery(undefined, { enabled: !!isOwner && section === "financeiro" });
  const recurring = trpc.business.finance.recurringList.useQuery(undefined, { enabled: !!isOwner && section === "financeiro" });
  const plans = trpc.business.plans.list.useQuery(undefined, { enabled: !!role && section === "planos" });
  const coupons = trpc.business.campaigns.coupons.useQuery(undefined, { enabled: !!isOwner && section === "promocoes" });
  const promotionList = trpc.business.campaigns.promotions.useQuery(undefined, { enabled: !!isOwner && section === "promocoes" });
  const subscriptions = trpc.business.subscriptions.list.useQuery(undefined, { enabled: !!role && section === "planos" });
  const customers = trpc.management.tenant.customers.useQuery({ search: "" }, { enabled: !!isOwner && section === "planos" });
  const services = trpc.management.tenant.services.useQuery(undefined, { enabled: !!role && (section === "planos" || section === "promocoes" || section === "relatorios" || section === "comissoes") });
  const products = trpc.business.inventory.products.useQuery(undefined, { enabled: !!role && section === "estoque" });
  const team = trpc.management.tenant.team.useQuery(undefined, { enabled: !!isOwner && (section === "comissoes" || section === "relatorios") });
  const commissionEntries = trpc.business.commissions.mine.useQuery(dateRange, { enabled: !!isBarber && section === "comissoes" });
  const commissionRules = trpc.business.commissions.rules.useQuery(undefined, { enabled: !!isOwner && section === "comissoes" });
  const commissionSummary = trpc.business.commissions.periodSummary.useQuery({ ...dateRange, barberId: barberFilter ? Number(barberFilter) : undefined }, { enabled: !!isOwner && section === "comissoes" });
  const settlements = trpc.business.commissions.settlements.useQuery({ ...dateRange }, { enabled: !!isOwner && section === "comissoes" });

  const refresh = async () => { await queryClient.invalidateQueries(); };
  const mutationOptions = (success: string) => ({ onSuccess: async () => { toast.success(success); await refresh(); }, onError: (error: { message: string }) => toast.error(error.message) });
  const openCash = trpc.business.finance.openCash.useMutation(mutationOptions("Caixa aberto."));
  const closeCash = trpc.business.finance.closeCash.useMutation({ onSuccess: async data => { toast.success(`Caixa fechado. Diferença: ${money(data.difference)}`); setCashCount(""); await refresh(); }, onError: error => toast.error(error.message) });
  const createTransaction = trpc.business.finance.createTransaction.useMutation(mutationOptions("Lançamento registrado."));
  const markPaid = trpc.business.finance.markPaid.useMutation(mutationOptions("Conta marcada como paga."));
  const createRecurring = trpc.business.finance.createRecurring.useMutation(mutationOptions("Despesa recorrente cadastrada."));
  const createPlan = trpc.business.plans.create.useMutation(mutationOptions("Plano cadastrado."));
  const createCoupon = trpc.business.campaigns.createCoupon.useMutation({ onSuccess: async () => { toast.success("Cupom criado."); setCouponForm(f => ({ ...f, code: "" })); await refresh(); }, onError: error => toast.error(error.message) });
  const setCouponActive = trpc.business.campaigns.setCouponActive.useMutation(mutationOptions("Status do cupom atualizado."));
  const createPromotion = trpc.business.campaigns.createPromotion.useMutation({ onSuccess: async () => { toast.success("Promoção cadastrada."); setPromotionForm(f => ({ ...f, name: "", serviceIds: [] })); await refresh(); }, onError: error => toast.error(error.message) });
  const setPromotionActive = trpc.business.campaigns.setPromotionActive.useMutation(mutationOptions("Status da promoção atualizado."));
  const updatePlan = trpc.business.plans.update.useMutation(mutationOptions("Plano atualizado."));
  const subscribe = trpc.business.plans.subscribe.useMutation(mutationOptions("Assinatura criada e pagamento lançado."));
  const recordPayment = trpc.business.plans.recordPayment.useMutation(mutationOptions("Mensalidade registrada."));
  const updateSubscription = trpc.business.subscriptions.updateStatus.useMutation(mutationOptions("Status da assinatura atualizado."));
  const createProduct = trpc.business.inventory.createProduct.useMutation(mutationOptions("Produto cadastrado."));
  const recordMovement = trpc.business.inventory.recordMovement.useMutation(mutationOptions("Movimentação de estoque registrada."));
  const configureRule = trpc.business.commissions.configureRule.useMutation(mutationOptions("Regra de comissão cadastrada."));
  const createSettlement = trpc.business.commissions.createSettlement.useMutation(mutationOptions("Fechamento de comissão criado."));
  const paySettlement = trpc.business.commissions.paySettlement.useMutation(mutationOptions("Comissão paga e lançada no financeiro."));

  const allowedSections: Section[] = isOwner ? ["caixa", "financeiro", "planos", "promocoes", "estoque", "comissoes", "relatorios"] : role === "receptionist" ? ["caixa", "planos"] : isBarber ? ["comissoes"] : [];
  const formatCsvCell = (value: unknown) => {
    const text = String(value ?? "");
    const safe = typeof value === "string" && /^[\t\r ]*[=+\-@]/.test(text) ? `'${text}` : text;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  const doCsvExport = () => {
    const rows = transactions.data ?? [];
    const header = ["Data", "Tipo", "Categoria", "Descrição", "Valor", "Taxa", "Forma de pagamento"];
    const amount = (value: number) => value.toLocaleString("pt-BR", { useGrouping: false, minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const body = rows.map(row => [row.paidAt?.toLocaleString("pt-BR") ?? "", row.kind === "income" ? "Receita" : "Despesa", row.category, row.description, amount(row.amount), amount(row.machineFee), row.paymentMethod ? methodName[row.paymentMethod] : ""]);
    const csv = [header, ...body].map(row => row.map(formatCsvCell).join(";")).join("\r\n");
    const url = URL.createObjectURL(new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8" }));
    const anchor = document.createElement("a"); anchor.href = url; anchor.download = `barbearia-relatorio-${from}-${to}.csv`; document.body.appendChild(anchor); anchor.click(); anchor.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  if (me.isPending) return <Loading/>;
  if (me.isError || !me.data) return <div className="grid min-h-screen place-items-center p-6"><div className="max-w-md rounded-xl border border-stone-200 bg-white p-6 text-center"><ShieldAlert className="mx-auto text-amber-800"/><h1 className="mt-3 font-serif text-2xl">Sessão não disponível</h1><p className="mt-2 text-sm text-stone-500">Entre novamente para acessar esta área.</p><button className={`${buttonClass} mt-4`} onClick={() => setLocation("/login")}>Ir para entrar</button></div></div>;
  if (!allowedSections.includes(section)) return <div className="grid min-h-screen place-items-center p-6 text-center"><div><ShieldAlert className="mx-auto text-amber-800"/><h1 className="mt-3 font-serif text-2xl">Acesso restrito</h1><p className="mt-2 text-sm text-stone-500">Este módulo não está disponível para o seu perfil.</p><button className={`${buttonClass} mt-4`} onClick={() => setLocation("/app")}>Voltar ao painel</button></div></div>;

  const nav: { key: Section; path: string }[] = allowedSections.map(key => ({ key, path: `/app/${key}` }));
  const onForm = (event: FormEvent, action: () => void) => { event.preventDefault(); action(); };
  const choosePeriod = (period: "today" | "week" | "month" | "previousMonth") => {
    const now = new Date();
    let start: Date;
    let end = now;
    if (period === "today") start = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    else if (period === "week") { start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - ((now.getDay() + 6) % 7)); }
    else if (period === "month") start = new Date(now.getFullYear(), now.getMonth(), 1);
    else { start = new Date(now.getFullYear(), now.getMonth() - 1, 1); end = new Date(now.getFullYear(), now.getMonth(), 0); }
    setFrom(dateKey(start)); setTo(dateKey(end));
  };
  const dateControls = <div className="flex flex-wrap items-end gap-3 rounded-lg border border-stone-200 bg-white p-4"><label className="text-xs text-stone-500">De<input className={inputClass} type="date" value={from} onChange={e => setFrom(e.target.value)}/></label><label className="text-xs text-stone-500">Até<input className={inputClass} type="date" value={to} onChange={e => setTo(e.target.value)}/></label><div className="flex flex-wrap gap-2">{([ ["today", "Hoje"], ["week", "Esta semana"], ["month", "Este mês"], ["previousMonth", "Mês anterior"] ] as const).map(([period, label]) => <button key={period} type="button" onClick={() => choosePeriod(period)} className={outlineClass}>{label}</button>)}</div></div>;

  return <div className="min-h-screen bg-[#f6f5f2] text-stone-800"><style>{"@media print { aside, header, button, input, select { display: none !important; } main { margin: 0 !important; } body { background: white !important; } article { break-inside: avoid; } }"}</style><aside className="fixed inset-y-0 left-0 z-30 hidden w-[250px] flex-col bg-[#20201d] lg:flex"><div className="flex h-[76px] items-center gap-3 px-6"><div className="grid h-10 w-10 place-items-center rounded-full border border-amber-700/40 text-amber-200"><Scissors size={18}/></div><div><p className="font-serif text-lg text-white">{me.data.shop.name}</p><p className="text-[10px] uppercase tracking-[.18em] text-stone-400">Gestão da barbearia</p></div></div><nav className="mt-5 space-y-1 px-3">{[{ key: "agenda" as const, path: "/app/agenda", label: "Agenda", icon: CalendarDays }, ...nav.map(item => ({ ...item, label: sectionLabels[item.key], icon: sectionIcons[item.key] }))].map(item => { const Icon = item.icon; return <button key={item.path} onClick={() => setLocation(item.path)} className={`flex w-full items-center gap-3 rounded-md px-3 py-3 text-left text-sm ${location === item.path ? "bg-white/10 text-amber-100" : "text-stone-300 hover:bg-white/5"}`}><Icon size={17}/>{item.label}</button>; })}</nav><div className="mt-auto border-t border-white/10 p-4"><p className="text-xs text-stone-300">{me.data.staff.name}</p><p className="mt-1 text-[10px] text-stone-500">{me.data.staff.role === "owner" ? "Dono" : me.data.staff.role === "barber" ? "Barbeiro" : "Recepção"}</p></div></aside>
    <main className="lg:ml-[250px]"><header className="sticky top-0 z-20 flex min-h-[66px] items-center justify-between border-b border-stone-200 bg-white/95 px-4 sm:px-7"><div className="flex items-center gap-3"><button className={outlineClass} onClick={() => setLocation("/app")}><ArrowLeft size={15}/><span className="hidden sm:inline">Painel</span></button><span className="text-xs text-stone-500">{me.data.shop.name} <span className="mx-1">/</span>{sectionLabels[section]}</span></div><span className="text-xs text-stone-500">{me.data.staff.name}</span></header><div className="mx-auto max-w-[1400px] px-4 pb-12 pt-7 sm:px-7 lg:px-10">
      <div className="mb-6"><p className="text-[10px] font-semibold uppercase tracking-[.2em] text-amber-800">Operação e gestão</p><h1 className="mt-1 font-serif text-3xl">{sectionLabels[section]}</h1><p className="mt-1 text-sm text-stone-500">Dados vinculados somente a {me.data.shop.name}.</p></div>
      <div className="mb-6 flex gap-2 overflow-x-auto pb-1 lg:hidden">{nav.map(item => { const Icon = sectionIcons[item.key]; return <button key={item.path} onClick={() => setLocation(item.path)} className={`${location === item.path ? "bg-stone-900 text-white" : "border border-stone-200 bg-white text-stone-700"} inline-flex shrink-0 items-center gap-2 rounded-md px-3 py-2 text-xs`}><Icon size={14}/>{sectionLabels[item.key]}</button>; })}</div>

      {section === "caixa" && <section className="space-y-5">{cash.isLoading ? <Loading/> : cash.isError ? <ErrorBox message={cash.error.message}/> : <div className="grid gap-4 lg:grid-cols-[1.1fr_.9fr]"><article className="rounded-xl border border-stone-200 bg-white p-5 sm:p-7"><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-amber-800">Situação do caixa</p><h2 className="mt-2 font-serif text-2xl">{cash.data?.isOpen ? "Caixa aberto" : "Nenhum caixa aberto"}</h2>{cash.data?.isOpen ? <><p className="mt-2 text-sm text-stone-500">Aberto em {cash.data.openedAt.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" })}</p><div className="mt-6 grid gap-3 sm:grid-cols-2"><Metric label="Fundo de abertura" value={money(cash.data.openingFloat)}/><Metric label="Saldo esperado em dinheiro" value={money(cash.data.expectedCash)}/></div><form onSubmit={e => onForm(e, () => { if (!cashCount) return toast.error("Informe o total contado."); closeCash.mutate({ countedTotal: Number(cashCount) }); })} className="mt-6 flex flex-wrap items-end gap-3 border-t border-stone-100 pt-5"><label className="min-w-48 flex-1 text-xs text-stone-500">Total contado no fechamento (R$)<input className={inputClass} required min="0" step="0.01" type="number" value={cashCount} onChange={e => setCashCount(e.target.value)}/></label><button disabled={closeCash.isPending} className={buttonClass}>{closeCash.isPending ? <LoaderCircle className="animate-spin" size={16}/> : <Check size={16}/>}Conferir e fechar</button></form></> : <form onSubmit={e => onForm(e, () => openCash.mutate({ openingFloat: Number(cashFloat || 0) }))} className="mt-6 flex flex-wrap items-end gap-3"><label className="min-w-48 flex-1 text-xs text-stone-500">Fundo inicial (R$)<input className={inputClass} min="0" step="0.01" type="number" value={cashFloat} onChange={e => setCashFloat(e.target.value)}/></label><button disabled={openCash.isPending} className={buttonClass}>{openCash.isPending ? <LoaderCircle className="animate-spin" size={16}/> : <Plus size={16}/>}Abrir caixa do dia</button></form>}</article><article className="rounded-xl border border-stone-200 bg-white p-5 sm:p-7"><h2 className="font-serif text-xl">Conferência</h2><p className="mt-2 text-sm leading-relaxed text-stone-500">O saldo esperado considera fundo de abertura e lançamentos em dinheiro associados ao caixa. Pix e cartões continuam nos relatórios financeiros, mas não entram no total físico contado.</p><p className="mt-5 rounded-md bg-stone-50 p-3 text-xs text-stone-600">As vendas e despesas pagas com caixa aberto são vinculadas automaticamente à sessão.</p></article></div>}</section>}

      {section === "financeiro" && <section className="space-y-5">{dateControls}{summary.isLoading ? <Loading/> : summary.isError ? <ErrorBox message={summary.error.message}/> : <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Receitas no período" value={money(summary.data?.income)} detail={`Período anterior: ${money(summary.data?.previous.income)}`}/><Metric label="Despesas pagas" value={money(summary.data?.expenses)} detail={`Período anterior: ${money(summary.data?.previous.expenses)}`}/><Metric label="Taxas de maquininha" value={money(summary.data?.machineFees)}/><Metric label="Resultado líquido" value={money(summary.data?.profit)} detail={`Anterior: ${money(summary.data?.previous.profit)}`}/><Metric label="Ticket médio" value={money(summary.data?.averageTicket)}/></div>}
        <div className="grid gap-5 xl:grid-cols-[1fr_1fr]"><form onSubmit={e => onForm(e, () => { if (!transactionForm.description.trim() || !transactionForm.amount) return toast.error("Preencha descrição e valor."); createTransaction.mutate({ kind: transactionForm.kind, category: transactionForm.category, description: transactionForm.description, amount: Number(transactionForm.amount), machineFee: Number(transactionForm.machineFee || 0), paymentMethod: transactionForm.dueAt ? null : transactionForm.paymentMethod, dueAt: transactionForm.dueAt ? asStart(transactionForm.dueAt) : null, paidAt: transactionForm.dueAt ? null : new Date(), recurring: false }); setTransactionForm(f => ({ ...f, description: "", amount: "", dueAt: "" })); })} className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Novo lançamento</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500">Tipo<select className={inputClass} value={transactionForm.kind} onChange={e => setTransactionForm({ ...transactionForm, kind: e.target.value as "income" | "expense" })}><option value="income">Receita</option><option value="expense">Despesa</option></select></label><label className="text-xs text-stone-500">Categoria<input className={inputClass} required value={transactionForm.category} onChange={e => setTransactionForm({ ...transactionForm, category: e.target.value })}/></label><label className="text-xs text-stone-500 sm:col-span-2">Descrição<input className={inputClass} required value={transactionForm.description} onChange={e => setTransactionForm({ ...transactionForm, description: e.target.value })}/></label><label className="text-xs text-stone-500">Valor (R$)<input className={inputClass} required min="0.01" step="0.01" type="number" value={transactionForm.amount} onChange={e => setTransactionForm({ ...transactionForm, amount: e.target.value })}/></label><label className="text-xs text-stone-500">Taxa da maquininha (R$)<input className={inputClass} min="0" step="0.01" type="number" value={transactionForm.machineFee} onChange={e => setTransactionForm({ ...transactionForm, machineFee: e.target.value })}/></label><label className="text-xs text-stone-500">Pagamento<select className={inputClass} value={transactionForm.paymentMethod} onChange={e => setTransactionForm({ ...transactionForm, paymentMethod: e.target.value as typeof transactionForm.paymentMethod })}><PaymentOptions/></select></label><label className="text-xs text-stone-500">Vencimento (opcional)<input className={inputClass} type="date" value={transactionForm.dueAt} onChange={e => setTransactionForm({ ...transactionForm, dueAt: e.target.value })}/></label></div><button disabled={createTransaction.isPending} className={`${buttonClass} mt-4`}>{createTransaction.isPending ? <LoaderCircle className="animate-spin" size={16}/> : <Plus size={16}/>}Registrar lançamento</button></form>
        <div className="space-y-4"><article className="rounded-xl border border-stone-200 bg-white p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-serif text-xl">Contas a pagar</h2><p className="mt-1 text-xs text-stone-500">Despesas com vencimento ainda não pagas.</p></div><span className="rounded-full bg-amber-50 px-3 py-1 text-xs text-amber-800">{payable.data?.length ?? 0} pendente(s)</span></div>{payable.isLoading ? <Loading/> : payable.data?.length ? <div className="mt-4 divide-y divide-stone-100">{payable.data.map(row => <div key={row.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="text-sm font-medium">{row.description}</p><p className="mt-1 text-xs text-stone-500">{row.category} · vencimento {row.dueAt?.toLocaleDateString("pt-BR") ?? "sem data"} · {money(row.amount)}</p></div><button onClick={() => markPaid.mutate({ transactionId: row.id, paymentMethod: "pix" })} className={outlineClass}>Marcar paga</button></div>)}</div> : <p className="mt-4 text-sm text-stone-500">Nenhuma conta pendente.</p>}</article>
        <article className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Despesas recorrentes</h2><form onSubmit={e => onForm(e, () => createRecurring.mutate({ ...recurringForm, amount: Number(recurringForm.amount), nextDueAt: asStart(recurringForm.nextDueAt) }))} className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500">Nome<input className={inputClass} required value={recurringForm.name} onChange={e => setRecurringForm({ ...recurringForm, name: e.target.value })}/></label><label className="text-xs text-stone-500">Categoria<input className={inputClass} required value={recurringForm.category} onChange={e => setRecurringForm({ ...recurringForm, category: e.target.value })}/></label><label className="text-xs text-stone-500">Valor<input className={inputClass} type="number" min="0.01" step="0.01" required value={recurringForm.amount} onChange={e => setRecurringForm({ ...recurringForm, amount: e.target.value })}/></label><label className="text-xs text-stone-500">Frequência<select className={inputClass} value={recurringForm.recurrence} onChange={e => setRecurringForm({ ...recurringForm, recurrence: e.target.value as typeof recurringForm.recurrence })}><option value="weekly">Semanal</option><option value="monthly">Mensal</option><option value="yearly">Anual</option></select></label><label className="text-xs text-stone-500">Próximo vencimento<input className={inputClass} type="date" required value={recurringForm.nextDueAt} onChange={e => setRecurringForm({ ...recurringForm, nextDueAt: e.target.value })}/></label><div className="flex items-end"><button className={buttonClass} disabled={createRecurring.isPending}><Plus size={15}/>Salvar recorrência</button></div></form>{recurring.data?.length ? <div className="mt-4 border-t border-stone-100 pt-3">{recurring.data.map(row => <p key={row.id} className="py-1.5 text-xs text-stone-600">{row.name} · {money(row.amount)} · próximo {row.nextDueAt.toLocaleDateString("pt-BR")}</p>)}</div> : null}</article></div></div>
        <TransactionsTable rows={transactions.data ?? []} loading={transactions.isLoading} error={transactions.error?.message} onCsv={doCsvExport} onPrint={() => window.print()} filters={{ kindFilter, setKindFilter, paymentFilter, setPaymentFilter }}/></section>}

      {section === "planos" && <section className="space-y-5">{isOwner && <div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><form onSubmit={e => onForm(e, () => { createPlan.mutate({ name: planForm.name, monthlyPrice: Number(planForm.monthlyPrice), usageLimit: planForm.usageLimit ? Number(planForm.usageLimit) : null, validityDays: planForm.validityDays ? Number(planForm.validityDays) : null, description: planForm.description || null, serviceIds: planForm.serviceIds, isActive: true }); })} className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Criar plano</h2><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500 sm:col-span-2">Nome<input className={inputClass} required value={planForm.name} onChange={e => setPlanForm({ ...planForm, name: e.target.value })}/></label><label className="text-xs text-stone-500">Mensalidade (R$)<input className={inputClass} required min="0.01" step="0.01" type="number" value={planForm.monthlyPrice} onChange={e => setPlanForm({ ...planForm, monthlyPrice: e.target.value })}/></label><label className="text-xs text-stone-500">Limite de usos (vazio = ilimitado)<input className={inputClass} min="1" type="number" value={planForm.usageLimit} onChange={e => setPlanForm({ ...planForm, usageLimit: e.target.value })}/></label><label className="text-xs text-stone-500">Validade (dias)<input className={inputClass} min="1" type="number" value={planForm.validityDays} onChange={e => setPlanForm({ ...planForm, validityDays: e.target.value })}/></label><label className="text-xs text-stone-500">Descrição<input className={inputClass} value={planForm.description} onChange={e => setPlanForm({ ...planForm, description: e.target.value })}/></label></div><div className="mt-4"><p className="text-xs font-medium text-stone-600">Serviços incluídos</p><div className="mt-2 flex flex-wrap gap-2">{(services.data ?? []).map(service => <label key={service.id} className="flex items-center gap-2 rounded-md border border-stone-200 px-3 py-2 text-xs"><input type="checkbox" checked={planForm.serviceIds.includes(service.id)} onChange={e => setPlanForm({ ...planForm, serviceIds: e.target.checked ? [...planForm.serviceIds, service.id] : planForm.serviceIds.filter(id => id !== service.id) })}/>{service.name}</label>)}</div></div><button disabled={createPlan.isPending} className={`${buttonClass} mt-4`}><Plus size={15}/>Cadastrar plano</button></form>
        <div className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Nova assinatura</h2><form onSubmit={e => onForm(e, () => subscribe.mutate({ customerId: Number(subscriptionForm.customerId), planId: Number(subscriptionForm.planId), paymentMethod: subscriptionForm.paymentMethod, amount: subscriptionForm.amount ? Number(subscriptionForm.amount) : undefined }))} className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500">Cliente<select required className={inputClass} value={subscriptionForm.customerId} onChange={e => setSubscriptionForm({ ...subscriptionForm, customerId: e.target.value })}><option value="">Selecione cliente</option>{(customers.data ?? []).map(customer => <option key={customer.id} value={customer.id}>{customer.name} · {customer.whatsapp}</option>)}</select></label><label className="text-xs text-stone-500">Plano<select required className={inputClass} value={subscriptionForm.planId} onChange={e => setSubscriptionForm({ ...subscriptionForm, planId: e.target.value })}><option value="">Selecione plano</option>{(plans.data ?? []).filter(p => p.isActive).map(plan => <option key={plan.id} value={plan.id}>{plan.name} · {money(plan.monthlyPrice)}</option>)}</select></label><label className="text-xs text-stone-500">Forma de pagamento<select className={inputClass} value={subscriptionForm.paymentMethod} onChange={e => setSubscriptionForm({ ...subscriptionForm, paymentMethod: e.target.value as typeof subscriptionForm.paymentMethod })}><PaymentOptions/></select></label><label className="text-xs text-stone-500">Valor pago (opcional)<input className={inputClass} min="0.01" step="0.01" type="number" value={subscriptionForm.amount} onChange={e => setSubscriptionForm({ ...subscriptionForm, amount: e.target.value })}/></label><div className="sm:col-span-2"><button className={buttonClass} disabled={subscribe.isPending}><Check size={15}/>Registrar assinatura e pagamento</button></div></form></div></div>}
        <article className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Planos cadastrados</h2>{plans.isLoading ? <Loading/> : <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{(plans.data ?? []).map(plan => <div key={plan.id} className="rounded-lg border border-stone-200 p-4"><div className="flex justify-between gap-3"><div><p className="font-medium">{plan.name}</p><p className="mt-1 text-sm text-stone-500">{money(plan.monthlyPrice)} / mês</p></div>{isOwner && <button className={outlineClass} onClick={() => updatePlan.mutate({ id: plan.id, isActive: !plan.isActive })}>{plan.isActive ? "Pausar" : "Ativar"}</button>}</div><p className="mt-3 text-xs text-stone-500">{plan.usageLimit ? `${plan.usageLimit} uso(s)` : "Uso ilimitado"} · {plan.validityDays ?? 30} dias</p><p className="mt-1 text-xs text-stone-500">{plan.serviceIds.length} serviço(s) incluído(s)</p></div>)}</div>}</article>
        <article className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Assinaturas</h2>{subscriptions.isLoading ? <Loading/> : <div className="mt-3 divide-y divide-stone-100">{(subscriptions.data ?? []).map(({ subscription, customerName, customerWhatsapp, planName, planPrice }) => <div key={subscription.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="font-medium">{customerName} <span className="font-normal text-stone-500">· {planName}</span></p><p className="mt-1 text-xs text-stone-500">{customerWhatsapp} · {statusName[subscription.status]} · termina {subscription.cycleEndsAt.toLocaleDateString("pt-BR")} · {money(planPrice)}</p></div>{isOwner && <div className="flex flex-wrap gap-2"><select aria-label="Status da assinatura" className="h-9 rounded-md border border-stone-200 bg-white px-2 text-xs" value={subscription.status} onChange={e => updateSubscription.mutate({ subscriptionId: subscription.id, status: e.target.value as typeof subscription.status })}>{(["active", "expired", "delinquent", "paused", "cancelled"] as const).map(status => <option key={status} value={status}>{statusName[status]}</option>)}</select><button className={outlineClass} onClick={() => { setRenewingId(renewingId === subscription.id ? null : subscription.id); setRenewAmount(String(planPrice)); }}>Registrar renovação</button></div>}{renewingId === subscription.id && isOwner && <form onSubmit={e => onForm(e, () => { recordPayment.mutate({ subscriptionId: subscription.id, amount: Number(renewAmount), paymentMethod: renewMethod as "cash" | "pix" | "credit" | "debit" | "other" }); setRenewingId(null); })} className="flex w-full flex-wrap items-end gap-2 rounded-md bg-stone-50 p-3"><label className="text-xs">Valor<input className={inputClass} type="number" min="0.01" step="0.01" value={renewAmount} onChange={e => setRenewAmount(e.target.value)}/></label><label className="text-xs">Pagamento<select className={inputClass} value={renewMethod} onChange={e => setRenewMethod(e.target.value)}><PaymentOptions/></select></label><button className={buttonClass}><Check size={15}/>Confirmar pagamento</button></form>}</div>)}{!subscriptions.data?.length && <p className="py-5 text-sm text-stone-500">Nenhuma assinatura cadastrada.</p>}</div>}</article></section>}

      {section === "promocoes" && <section className="space-y-5"><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><form onSubmit={e => onForm(e, () => createCoupon.mutate({ code: couponForm.code.trim().toUpperCase(), discountType: couponForm.discountType, discountValue: Number(couponForm.discountValue), validFrom: couponForm.validFrom ? asStart(couponForm.validFrom) : null, validUntil: couponForm.validUntil ? asEnd(couponForm.validUntil) : null, usageLimit: couponForm.usageLimit ? Number(couponForm.usageLimit) : null }))} className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Criar cupom</h2><p className="mt-1 text-xs text-stone-500">O código é aplicado no agendamento público quando cupons estiverem ativados nas configurações.</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500 sm:col-span-2">Código<input className={inputClass} required minLength={3} maxLength={48} pattern="[A-Za-z0-9_-]+" value={couponForm.code} onChange={e => setCouponForm({ ...couponForm, code: e.target.value.replace(/\s/g, "").toUpperCase() })} placeholder="PRIME10"/></label><label className="text-xs text-stone-500">Tipo de desconto<select className={inputClass} value={couponForm.discountType} onChange={e => setCouponForm({ ...couponForm, discountType: e.target.value as "percentage" | "fixed" })}><option value="percentage">Percentual</option><option value="fixed">Valor fixo (R$)</option></select></label><label className="text-xs text-stone-500">Desconto{couponForm.discountType === "percentage" ? " (%)" : " (R$)"}<input className={inputClass} required min="0.01" max={couponForm.discountType === "percentage" ? "100" : undefined} step="0.01" type="number" value={couponForm.discountValue} onChange={e => setCouponForm({ ...couponForm, discountValue: e.target.value })}/></label><label className="text-xs text-stone-500">Válido a partir de<input className={inputClass} type="date" value={couponForm.validFrom} onChange={e => setCouponForm({ ...couponForm, validFrom: e.target.value })}/></label><label className="text-xs text-stone-500">Válido até<input className={inputClass} type="date" value={couponForm.validUntil} onChange={e => setCouponForm({ ...couponForm, validUntil: e.target.value })}/></label><label className="text-xs text-stone-500 sm:col-span-2">Limite de usos (vazio = sem limite)<input className={inputClass} min="1" step="1" type="number" value={couponForm.usageLimit} onChange={e => setCouponForm({ ...couponForm, usageLimit: e.target.value })}/></label></div><button className={`${buttonClass} mt-4`} disabled={createCoupon.isPending}>{createCoupon.isPending ? <LoaderCircle className="animate-spin" size={15}/> : <Plus size={15}/>}Salvar cupom</button></form><article className="rounded-xl border border-stone-200 bg-white p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-serif text-xl">Cupons cadastrados</h2><p className="mt-1 text-xs text-stone-500">Usos: {coupons.data?.reduce((sum, coupon) => sum + coupon.usageCount, 0) ?? 0} no total.</p></div><span className="rounded-full bg-amber-50 px-3 py-1 text-xs text-amber-800">{coupons.data?.length ?? 0} código(s)</span></div>{coupons.isLoading ? <Loading/> : coupons.isError ? <ErrorBox message={coupons.error.message}/> : coupons.data?.length ? <div className="mt-4 divide-y divide-stone-100">{coupons.data.map(coupon => <div key={coupon.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="font-mono text-sm font-semibold tracking-wider">{coupon.code}<span className={`ml-2 rounded-full px-2 py-1 font-sans text-[9px] ${coupon.isActive ? "bg-emerald-50 text-emerald-800" : "bg-stone-100 text-stone-500"}`}>{coupon.isActive ? "Ativo" : "Pausado"}</span></p><p className="mt-1 text-xs text-stone-500">{coupon.discountType === "percentage" ? `${coupon.discountValue}%` : money(coupon.discountValue)} de desconto · {coupon.usageCount}{coupon.usageLimit ? `/${coupon.usageLimit}` : ""} uso(s){coupon.validFrom ? ` · desde ${coupon.validFrom.toLocaleDateString("pt-BR")}` : ""}{coupon.validUntil ? ` · até ${coupon.validUntil.toLocaleDateString("pt-BR")}` : ""}</p></div><button className={outlineClass} onClick={() => setCouponActive.mutate({ id: coupon.id, isActive: !coupon.isActive })}>{coupon.isActive ? "Pausar" : "Ativar"}</button></div>)}</div> : <p className="mt-4 text-sm text-stone-500">Nenhum cupom cadastrado.</p>}<p className="mt-4 border-t border-stone-100 pt-3 text-[11px] leading-relaxed text-stone-500">A validade e o limite de usos são verificados no servidor quando o cliente confirma a reserva.</p></article></div>
        <div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><form onSubmit={e => onForm(e, () => createPromotion.mutate({ name: promotionForm.name.trim(), kind: promotionForm.kind, discountType: promotionForm.discountType, discountValue: Number(promotionForm.discountValue), serviceIds: promotionForm.serviceIds, daysOfWeek: promotionForm.daysOfWeek, startTime: promotionForm.kind === "time_discount" ? promotionForm.startTime : null, endTime: promotionForm.kind === "time_discount" ? promotionForm.endTime : null, startsAt: promotionForm.startsAt ? asStart(promotionForm.startsAt) : null, endsAt: promotionForm.endsAt ? asEnd(promotionForm.endsAt) : null }))} className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Criar promoção</h2><p className="mt-1 text-xs text-stone-500">A melhor oferta elegível é aplicada ao horário escolhido; promoções não acumulam entre si.</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500 sm:col-span-2">Nome da promoção<input className={inputClass} required minLength={2} maxLength={160} value={promotionForm.name} onChange={e => setPromotionForm({ ...promotionForm, name: e.target.value })} placeholder="Corte em horário tranquilo"/></label><label className="text-xs text-stone-500">Tipo<select className={inputClass} value={promotionForm.kind} onChange={e => setPromotionForm({ ...promotionForm, kind: e.target.value as typeof promotionForm.kind })}><option value="service_discount">Desconto em serviço(s)</option><option value="time_discount">Dia e horário</option><option value="combo">Combo de serviços</option></select></label><label className="text-xs text-stone-500">Desconto<select className={inputClass} value={promotionForm.discountType} onChange={e => setPromotionForm({ ...promotionForm, discountType: e.target.value as "percentage" | "fixed" })}><option value="percentage">Percentual</option><option value="fixed">Valor fixo (R$)</option></select></label><label className="text-xs text-stone-500">Valor{promotionForm.discountType === "percentage" ? " (%)" : " (R$)"}<input className={inputClass} required type="number" min="0.01" max={promotionForm.discountType === "percentage" ? "100" : undefined} step="0.01" value={promotionForm.discountValue} onChange={e => setPromotionForm({ ...promotionForm, discountValue: e.target.value })}/></label><label className="text-xs text-stone-500">Começa em<input className={inputClass} type="date" value={promotionForm.startsAt} onChange={e => setPromotionForm({ ...promotionForm, startsAt: e.target.value })}/></label><label className="text-xs text-stone-500">Termina em<input className={inputClass} type="date" value={promotionForm.endsAt} onChange={e => setPromotionForm({ ...promotionForm, endsAt: e.target.value })}/></label>
          {promotionForm.kind === "time_discount" && <><fieldset className="sm:col-span-2"><legend className="text-xs text-stone-500">Dias da semana</legend><div className="mt-2 flex flex-wrap gap-2">{["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"].map((label, day) => <label key={day} className={`flex items-center gap-1.5 rounded-md border px-2.5 py-2 text-xs ${promotionForm.daysOfWeek.includes(day) ? "border-amber-700 bg-amber-50 text-amber-900" : "border-stone-200 text-stone-600"}`}><input type="checkbox" checked={promotionForm.daysOfWeek.includes(day)} onChange={() => setPromotionForm(f => ({ ...f, daysOfWeek: f.daysOfWeek.includes(day) ? f.daysOfWeek.filter(value => value !== day) : [...f.daysOfWeek, day] }))}/>{label}</label>)}</div></fieldset><label className="text-xs text-stone-500">Das<input className={inputClass} type="time" required value={promotionForm.startTime} onChange={e => setPromotionForm({ ...promotionForm, startTime: e.target.value })}/></label><label className="text-xs text-stone-500">Até<input className={inputClass} type="time" required value={promotionForm.endTime} onChange={e => setPromotionForm({ ...promotionForm, endTime: e.target.value })}/></label></>}
          <fieldset className="sm:col-span-2"><legend className="text-xs text-stone-500">Serviços incluídos{promotionForm.kind === "time_discount" ? " (opcional; vazio = todos)" : promotionForm.kind === "combo" ? " (selecione ao menos dois)" : " (selecione ao menos um)"}</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{services.data?.map(service => <label key={service.id} className="flex items-center gap-2 rounded-md border border-stone-200 px-3 py-2 text-xs"><input type="checkbox" checked={promotionForm.serviceIds.includes(service.id)} onChange={() => setPromotionForm(f => ({ ...f, serviceIds: f.serviceIds.includes(service.id) ? f.serviceIds.filter(value => value !== service.id) : [...f.serviceIds, service.id] }))}/>{service.name}<span className="ml-auto text-stone-500">{money(service.price)}</span></label>)}</div>{!services.isLoading && !services.data?.length && <p className="mt-2 text-xs text-stone-500">Cadastre serviços antes de criar promoções.</p>}</fieldset></div><button className={`${buttonClass} mt-4`} disabled={createPromotion.isPending || services.isLoading}>{createPromotion.isPending ? <LoaderCircle className="animate-spin" size={15}/> : <Plus size={15}/>}Salvar promoção</button></form>
          <article className="rounded-xl border border-stone-200 bg-white p-5"><div className="flex items-center justify-between gap-3"><div><h2 className="font-serif text-xl">Promoções cadastradas</h2><p className="mt-1 text-xs text-stone-500">Descontos por serviço, combos e horários definidos.</p></div><span className="rounded-full bg-amber-50 px-3 py-1 text-xs text-amber-800">{promotionList.data?.length ?? 0} promoção(ões)</span></div>{promotionList.isLoading ? <Loading/> : promotionList.isError ? <ErrorBox message={promotionList.error.message}/> : promotionList.data?.length ? <div className="mt-4 divide-y divide-stone-100">{promotionList.data.map(promotion => <div key={promotion.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="font-medium text-sm">{promotion.name}<span className={`ml-2 rounded-full px-2 py-1 text-[9px] ${promotion.isActive ? "bg-emerald-50 text-emerald-800" : "bg-stone-100 text-stone-500"}`}>{promotion.isActive ? "Ativa" : "Pausada"}</span></p><p className="mt-1 text-xs text-stone-500">{campaignKindLabel[promotion.kind]} · {promotion.discountType === "percentage" ? `${promotion.discountValue}%` : money(promotion.discountValue)} de desconto{promotion.startsAt ? ` · desde ${promotion.startsAt.toLocaleDateString("pt-BR")}` : ""}{promotion.endsAt ? ` · até ${promotion.endsAt.toLocaleDateString("pt-BR")}` : ""}</p></div><button className={outlineClass} onClick={() => setPromotionActive.mutate({ id: promotion.id, isActive: !promotion.isActive })}>{promotion.isActive ? "Pausar" : "Ativar"}</button></div>)}</div> : <p className="mt-4 text-sm text-stone-500">Nenhuma promoção cadastrada.</p>}<p className="mt-4 border-t border-stone-100 pt-3 text-[11px] leading-relaxed text-stone-500">As datas, serviços e horários são revalidados no servidor junto com a disponibilidade antes de confirmar o agendamento.</p></article></div></section>}

      {section === "estoque" && <section className="space-y-5"><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><form onSubmit={e => onForm(e, () => createProduct.mutate({ name: productForm.name, sku: productForm.sku || null, costPrice: Number(productForm.costPrice || 0), salePrice: Number(productForm.salePrice || 0), quantity: Number(productForm.quantity), minimumQuantity: Number(productForm.minimumQuantity), useInternally: productForm.useInternally }))} className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Cadastrar produto</h2><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500 sm:col-span-2">Produto<input className={inputClass} required value={productForm.name} onChange={e => setProductForm({ ...productForm, name: e.target.value })}/></label><label className="text-xs text-stone-500">SKU<input className={inputClass} value={productForm.sku} onChange={e => setProductForm({ ...productForm, sku: e.target.value })}/></label><label className="text-xs text-stone-500">Custo (R$)<input className={inputClass} min="0" step="0.01" type="number" value={productForm.costPrice} onChange={e => setProductForm({ ...productForm, costPrice: e.target.value })}/></label><label className="text-xs text-stone-500">Preço de venda (R$)<input className={inputClass} min="0" step="0.01" type="number" value={productForm.salePrice} onChange={e => setProductForm({ ...productForm, salePrice: e.target.value })}/></label><label className="text-xs text-stone-500">Quantidade inicial<input className={inputClass} min="0" type="number" value={productForm.quantity} onChange={e => setProductForm({ ...productForm, quantity: e.target.value })}/></label><label className="text-xs text-stone-500">Estoque mínimo<input className={inputClass} min="0" type="number" value={productForm.minimumQuantity} onChange={e => setProductForm({ ...productForm, minimumQuantity: e.target.value })}/></label><label className="flex items-center gap-2 pt-5 text-xs text-stone-600"><input type="checkbox" checked={productForm.useInternally} onChange={e => setProductForm({ ...productForm, useInternally: e.target.checked })}/>Uso interno</label></div><button className={`${buttonClass} mt-4`} disabled={createProduct.isPending}><Plus size={15}/>Cadastrar</button></form>
        <div className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Movimentar estoque</h2><form onSubmit={e => onForm(e, () => recordMovement.mutate({ productId: Number(movementForm.productId), kind: movementForm.kind, quantity: Number(movementForm.quantity), note: movementForm.note || undefined }))} className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500 sm:col-span-2">Produto<select required className={inputClass} value={movementForm.productId} onChange={e => setMovementForm({ ...movementForm, productId: e.target.value })}><option value="">Selecione</option>{(products.data ?? []).map(p => <option key={p.id} value={p.id}>{p.name} · estoque {p.quantity}</option>)}</select></label><label className="text-xs text-stone-500">Movimento<select className={inputClass} value={movementForm.kind} onChange={e => setMovementForm({ ...movementForm, kind: e.target.value as typeof movementForm.kind })}><option value="in">Entrada</option><option value="out">Saída</option><option value="internal_use">Uso interno</option><option value="adjustment">Ajuste para a quantidade informada</option></select></label><label className="text-xs text-stone-500">Quantidade<input className={inputClass} required min="1" type="number" value={movementForm.quantity} onChange={e => setMovementForm({ ...movementForm, quantity: e.target.value })}/></label><label className="text-xs text-stone-500 sm:col-span-2">Observação<input className={inputClass} value={movementForm.note} onChange={e => setMovementForm({ ...movementForm, note: e.target.value })}/></label><div><button className={buttonClass} disabled={recordMovement.isPending}>Registrar movimento</button></div></form></div></div>
        <article className="rounded-xl border border-stone-200 bg-white p-5"><div className="flex items-center justify-between"><h2 className="font-serif text-xl">Produtos</h2><span className="text-xs text-stone-500">{products.data?.length ?? 0} cadastrado(s)</span></div>{products.isLoading ? <Loading/> : <div className="mt-4 overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead className="border-b border-stone-100 text-[10px] uppercase tracking-wider text-stone-500"><tr><th className="py-3">Produto</th><th>Estoque</th><th>Mínimo</th><th>Custo</th><th>Venda</th><th>Alerta</th></tr></thead><tbody className="divide-y divide-stone-100">{(products.data ?? []).map(p => <tr key={p.id}><td className="py-3 font-medium">{p.name}</td><td>{p.quantity}</td><td>{"minimumQuantity" in p ? p.minimumQuantity : "—"}</td><td>{"costPrice" in p ? money(p.costPrice) : "—"}</td><td>{money(p.salePrice)}</td><td>{"minimumQuantity" in p && p.quantity <= p.minimumQuantity ? <span className="rounded-full bg-rose-50 px-2 py-1 text-[10px] text-rose-700">Repor</span> : <span className="text-xs text-emerald-700">OK</span>}</td></tr>)}</tbody></table>{!products.data?.length && <p className="py-5 text-sm text-stone-500">Nenhum produto cadastrado.</p>}</div>}</article></section>}

      {section === "comissoes" && (isBarber ? <section className="space-y-5">{dateControls}<article className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Suas comissões</h2>{commissionEntries.isLoading ? <Loading/> : commissionEntries.isError ? <ErrorBox message={commissionEntries.error.message}/> : <><div className="mt-4 grid gap-3 sm:grid-cols-2"><Metric label="Total no período" value={money((commissionEntries.data ?? []).reduce((sum, row) => sum + row.amount, 0))}/><Metric label="Lançamentos" value={String(commissionEntries.data?.length ?? 0)}/></div><div className="mt-4 divide-y divide-stone-100">{(commissionEntries.data ?? []).map(entry => <div key={entry.id} className="flex justify-between gap-3 py-3 text-sm"><span>{entry.description}<span className="ml-2 text-xs text-stone-500">{entry.createdAt.toLocaleDateString("pt-BR")}</span></span><strong>{money(entry.amount)}</strong></div>)}</div>{!commissionEntries.data?.length && <p className="mt-4 text-sm text-stone-500">Sem comissões registradas no período.</p>}</>}</article></section> : <section className="space-y-5">{dateControls}<div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><form onSubmit={e => onForm(e, () => configureRule.mutate({ barberId: Number(commissionForm.barberId), serviceId: commissionForm.scope === "service" && commissionForm.serviceId ? Number(commissionForm.serviceId) : null, scope: commissionForm.scope, calculation: commissionForm.calculation, value: Number(commissionForm.value), planPercentage: Number(commissionForm.planPercentage) }))} className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Regra de comissão</h2><div className="mt-3 grid gap-3"><label className="text-xs text-stone-500">Barbeiro<select required className={inputClass} value={commissionForm.barberId} onChange={e => setCommissionForm({ ...commissionForm, barberId: e.target.value })}><option value="">Selecione</option>{(team.data?.barbers ?? []).map(b => <option key={b.id} value={b.id}>{b.displayName}</option>)}</select></label><label className="text-xs text-stone-500">Aplicação<select className={inputClass} value={commissionForm.scope} onChange={e => setCommissionForm({ ...commissionForm, scope: e.target.value as typeof commissionForm.scope })}><option value="all">Todos os serviços</option><option value="service">Serviço específico</option><option value="product">Produtos</option><option value="plan">Atendimento por plano</option></select></label>{commissionForm.scope === "service" && <label className="text-xs text-stone-500">Serviço<select className={inputClass} value={commissionForm.serviceId} onChange={e => setCommissionForm({ ...commissionForm, serviceId: e.target.value })}><option value="">Regra geral</option>{(services.data ?? []).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label>}<label className="text-xs text-stone-500">Cálculo<select className={inputClass} value={commissionForm.calculation} onChange={e => setCommissionForm({ ...commissionForm, calculation: e.target.value as typeof commissionForm.calculation })}><option value="percentage">Percentual</option><option value="fixed_per_service">Valor fixo por serviço/unidade</option><option value="chair_rent">Aluguel de cadeira</option></select></label><label className="text-xs text-stone-500">Valor (% ou R$)<input className={inputClass} type="number" min="0" step="0.01" value={commissionForm.value} onChange={e => setCommissionForm({ ...commissionForm, value: e.target.value })}/></label><label className="text-xs text-stone-500">Percentual para serviços cobertos por plano<input className={inputClass} type="number" min="0" max="100" step="0.01" value={commissionForm.planPercentage} onChange={e => setCommissionForm({ ...commissionForm, planPercentage: e.target.value })}/></label></div><button className={`${buttonClass} mt-4`} disabled={configureRule.isPending}>Salvar regra</button></form>
        <div className="space-y-5"><article className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Fechamento do período</h2><form onSubmit={e => onForm(e, () => createSettlement.mutate({ ...dateRange, barberId: Number(settlementForm.barberId), discounts: Number(settlementForm.discounts), advances: Number(settlementForm.advances) }))} className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-xs text-stone-500">Barbeiro<select required className={inputClass} value={settlementForm.barberId} onChange={e => setSettlementForm({ ...settlementForm, barberId: e.target.value })}><option value="">Selecione</option>{(team.data?.barbers ?? []).map(b => <option key={b.id} value={b.id}>{b.displayName}</option>)}</select></label><label className="text-xs text-stone-500">Descontos (R$)<input className={inputClass} type="number" min="0" step="0.01" value={settlementForm.discounts} onChange={e => setSettlementForm({ ...settlementForm, discounts: e.target.value })}/></label><label className="text-xs text-stone-500">Vales/adiantamentos (R$)<input className={inputClass} type="number" min="0" step="0.01" value={settlementForm.advances} onChange={e => setSettlementForm({ ...settlementForm, advances: e.target.value })}/></label><div className="flex items-end"><button className={buttonClass} disabled={createSettlement.isPending}>Criar fechamento</button></div></form><p className="mt-3 text-xs text-stone-500">Comissões acumuladas no período: {money(commissionSummary.data?.total)}</p></article><article className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Fechamentos</h2>{(settlements.data ?? []).map(({ settlement, barberName }) => <div key={settlement.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-stone-100 py-3"><div><p className="text-sm font-medium">{barberName}</p><p className="mt-1 text-xs text-stone-500">{settlement.periodStart.toLocaleDateString("pt-BR")}–{settlement.periodEnd.toLocaleDateString("pt-BR")} · bruto {money(settlement.grossAmount)} · líquido {money(settlement.netAmount)} · {statusName[settlement.status]}</p></div>{settlement.status === "open" && <div className="flex items-center gap-2"><select className="h-9 rounded-md border border-stone-200 bg-white px-2 text-xs" value={settlementPayment} onChange={e => setSettlementPayment(e.target.value)}><PaymentOptions/></select><button className={outlineClass} onClick={() => paySettlement.mutate({ settlementId: settlement.id, paymentMethod: settlementPayment as "cash" | "pix" | "credit" | "debit" | "other" })}>Marcar pago</button></div>}</div>)}{!settlements.data?.length && <p className="mt-3 text-sm text-stone-500">Nenhum fechamento neste período.</p>}</article><article className="rounded-xl border border-stone-200 bg-white p-5"><h2 className="font-serif text-xl">Regras ativas</h2>{(commissionRules.data ?? []).map(rule => <p key={rule.id} className="border-b border-stone-100 py-2 text-xs text-stone-600">Barbeiro #{rule.barberId} · {rule.scope} · {rule.calculation} · {rule.value}{rule.calculation === "percentage" ? "%" : " R$"} · plano {rule.planPercentage}%</p>)}</article></div></div></section>)}

      {section === "relatorios" && <section className="space-y-5">{dateControls}<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Receitas filtradas" value={money((transactions.data ?? []).filter(r => r.kind === "income").reduce((n,r) => n+r.amount, 0))}/><Metric label="Despesas filtradas" value={money((transactions.data ?? []).filter(r => r.kind === "expense").reduce((n,r) => n+r.amount, 0))}/><Metric label="Taxas filtradas" value={money((transactions.data ?? []).reduce((n,r) => n+r.machineFee, 0))}/><Metric label="Resultado líquido" value={money((transactions.data ?? []).filter(r => r.kind === "income").reduce((n,r) => n+r.amount, 0) - (transactions.data ?? []).filter(r => r.kind === "expense").reduce((n,r) => n+r.amount, 0) - (transactions.data ?? []).reduce((n,r) => n+r.machineFee, 0))}/></div><div className="grid gap-3 rounded-lg border border-stone-200 bg-white p-4 sm:grid-cols-3"><label className="text-xs text-stone-500">Barbeiro<select className={inputClass} value={barberFilter} onChange={e => setBarberFilter(e.target.value)}><option value="">Todos</option>{(team.data?.barbers ?? []).map(b => <option key={b.id} value={b.id}>{b.displayName}</option>)}</select></label><label className="text-xs text-stone-500">Serviço<select className={inputClass} value={serviceFilter} onChange={e => setServiceFilter(e.target.value)}><option value="">Todos</option>{(services.data ?? []).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="text-xs text-stone-500">Forma de pagamento<select className={inputClass} value={paymentFilter} onChange={e => setPaymentFilter(e.target.value)}><option value="">Todas</option><PaymentOptions/></select></label></div><TransactionsTable rows={transactions.data ?? []} loading={transactions.isLoading} error={transactions.error?.message} onCsv={doCsvExport} onPrint={() => window.print()} filters={{ kindFilter, setKindFilter, paymentFilter, setPaymentFilter }}/></section>}
      </div></main></div>;
}

function PaymentOptions() { return <><option value="cash">Dinheiro</option><option value="pix">Pix</option><option value="credit">Crédito</option><option value="debit">Débito</option><option value="other">Outro</option></>; }
function Loading() { return <div className="flex min-h-24 items-center justify-center gap-2 text-sm text-stone-500"><LoaderCircle className="animate-spin" size={17}/>Carregando…</div>; }
function ErrorBox({ message }: { message: string }) { return <div role="alert" className="rounded-lg border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800">Não foi possível carregar os dados: {message}</div>; }
function Metric({ label, value, detail }: { label: string; value: string; detail?: string }) { return <article className="rounded-lg border border-stone-200 bg-white p-4"><p className="text-[10px] font-semibold uppercase tracking-wider text-stone-500">{label}</p><p className="mt-2 font-serif text-2xl">{value}</p>{detail && <p className="mt-1 text-[10px] text-stone-500">{detail}</p>}</article>; }
function TransactionsTable({ rows, loading, error, onCsv, onPrint, filters }: { rows: Array<{ id: number; kind: string; category: string; description: string; amount: number; machineFee: number; paymentMethod: string | null; paidAt: Date | null }>; loading: boolean; error?: string; onCsv: () => void; onPrint: () => void; filters: { kindFilter: string; setKindFilter: (value: "all" | "income" | "expense") => void; paymentFilter: string; setPaymentFilter: (value: string) => void } }) { return <article className="rounded-xl border border-stone-200 bg-white p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-serif text-xl">Movimentações</h2><p className="mt-1 text-xs text-stone-500">Filtre o período e exporte os dados para planilha ou impressão/PDF.</p></div><div className="flex gap-2"><button className={outlineClass} onClick={onCsv}><Download size={15}/>Excel/CSV</button><button className={outlineClass} onClick={onPrint}><Printer size={15}/>Imprimir/PDF</button></div></div><div className="mt-4 flex flex-wrap gap-2"><select className="h-9 rounded-md border border-stone-200 bg-white px-2 text-xs" value={filters.kindFilter} onChange={e => filters.setKindFilter(e.target.value as "all" | "income" | "expense")}><option value="all">Receitas e despesas</option><option value="income">Receitas</option><option value="expense">Despesas</option></select><select className="h-9 rounded-md border border-stone-200 bg-white px-2 text-xs" value={filters.paymentFilter} onChange={e => filters.setPaymentFilter(e.target.value)}><option value="">Todos os pagamentos</option><PaymentOptions/></select></div>{loading ? <Loading/> : error ? <ErrorBox message={error}/> : <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="border-b border-stone-100 text-[10px] uppercase tracking-wider text-stone-500"><tr><th className="py-3">Data</th><th>Movimentação</th><th>Categoria</th><th>Pagamento</th><th>Valor</th><th>Taxa</th></tr></thead><tbody className="divide-y divide-stone-100">{rows.map(row => <tr key={row.id}><td className="py-3 text-xs">{row.paidAt?.toLocaleString("pt-BR") ?? "—"}</td><td><span className={row.kind === "income" ? "text-emerald-700" : "text-rose-700"}>{row.kind === "income" ? "Receita" : "Despesa"}</span><p className="mt-1 text-xs text-stone-500">{row.description}</p></td><td className="text-xs">{row.category}</td><td className="text-xs">{row.paymentMethod ? methodName[row.paymentMethod] : "—"}</td><td className="font-medium">{money(row.amount)}</td><td className="text-xs">{money(row.machineFee)}</td></tr>)}</tbody></table>{!rows.length && <p className="py-6 text-center text-sm text-stone-500">Sem movimentações para estes filtros.</p>}</div>}</article>; }
